import osfrom pathlib import Pathimport pymysqlfrom dotenv import load_dotenvfrom pymysql.cursors import DictCursorfrom dbutils.pooled_db import PooledDBfrom sqlalchemy import create_enginefrom sqlalchemy.orm import sessionmaker, declarative_basefrom starlette.exceptions import HTTPExceptionBASE_DIR = Path(__file__).resolve().parentdotenv_db_path = BASE_DIR / ".env_DB"# verbose=True를 넣으면 로드 과정을 상세히 출력해줍니다.if load_dotenv(dotenv_path=dotenv_db_path, verbose=True):    print(f"✅ .env_DB 로드 성공! (경로: {dotenv_db_path})")else:    print(f"❌ .env_DB 로드 실패! (파일이 해당 경로에 있는지 확인하세요: {dotenv_db_path})")def get_env(key:str, default=None):    value = os.getenv(key, default)    if value is None:        raise RuntimeError(f"환경변수 누락 : {key}")    return valuedb_config = {    "host": get_env("MYSQL_HOST","localhost"),    "port": int(get_env("MYSQL_PORT", 3306)),    "db": get_env("MYSQL_DB", "my_app"),    "user": get_env("MYSQL_USER","root"),    "password": get_env("MYSQL_PASSWORD"),    "charset": get_env("MYSQL_CHARSET","utf8mb4"),    "cursorclass" : DictCursor}pools = PooledDB(    creator=pymysql,    mincached=5,    maxcached=10,    maxconnections=20,    blocking=True, # 풀이 찼을 때 대기 여부    **db_config)def get_db_connection():    return pools.connection()def get_db():    conn = get_db_connection()    try:        yield conn    except Exception as e:        print(f"DB error: {e}")        raise HTTPException(status_code=500, detail="데이터베이스 오류가 발생했습니다.")    finally:        conn.close()## DATABASE_URL = f"mysql+pymysql://{db_config["user"]}:{ db_config["password"]}@{db_config["host"]}:{ db_config["port"]}/{ db_config["db"]}?charset=utf8mb4"## # 2. SQLAlchemy 엔진 생성 (애플리케이션 전체에서 하나만 생성)# engine = create_engine(DATABASE_URL, echo=True, pool_pre_ping=True)# SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)# Base = declarative_base()## # ---------------------------------------------------------# # 방식 A: SQLAlchemy ORM 사용 시# # ---------------------------------------------------------# def use_orm():#     db = SessionLocal()#     try:#         # user = db.query(User).first()#         pass#     finally:#         db.close()## # ---------------------------------------------------------# # 방식 B: PyMySQL처럼 Raw Query (Native) 사용 시# # ---------------------------------------------------------# def use_native_query():#     # 별도의 PyMySQL 커넥션을 맺지 않고, engine에서 바로 커넥션을 빌려옵니다.#     # 이 방식이 성능과 커넥션 풀 관리 면에서 훨씬 유리합니다.#     with engine.connect() as connection:#         result = connection.execute(text("SELECT * FROM users WHERE id = :id"), {"id": 1})#         for row in result:#             print(row)